CREATE TABLE IF NOT EXISTS public.hire_purchase_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, sale_id uuid NOT NULL UNIQUE REFERENCES public.sales(id) ON DELETE CASCADE, duration_months integer NOT NULL CHECK (duration_months > 0), installment_frequency text NOT NULL CHECK (installment_frequency IN ('WEEKLY','BIWEEKLY','MONTHLY')), total_payable numeric NOT NULL CHECK (total_payable >= 0), installment_amount numeric NOT NULL CHECK (installment_amount >= 0), first_due_date date NOT NULL, ownership_status text NOT NULL DEFAULT 'RETAINED', created_at timestamptz NOT NULL DEFAULT now());